#!/usr/bin/env python3
from pathlib import Path
import hashlib,json
import pandas as pd
ROOT=Path('/home/ubuntu/CHAOS'); SRC=ROOT/'campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH'; RAW=SRC/'raw/imf_imts_wdi_target_ready_xg_v2'; ACQ=json.loads((SRC/'IMF_IMTS_WDI_READY_XG_ACQUISITION_SUMMARY_V2.json').read_text()); OUT=ROOT/'experiments/multi_domain_native_adapters_v1/imf_imts_v2'; OUT.mkdir(parents=True,exist_ok=True); files=sorted(RAW.glob('*.csv')); frames=[]; per=[]
for p in files:
 df=pd.read_csv(p,usecols=['COUNTRY','INDICATOR','COUNTERPART_COUNTRY','FREQUENCY','TIME_PERIOD','OBS_VALUE','SCALE','TRADE_FLOW','VALUATION','UNIT'],dtype=str,low_memory=False); df=df.rename(columns={'COUNTRY':'country','INDICATOR':'indicator','COUNTERPART_COUNTRY':'counterpart_country','FREQUENCY':'frequency','TIME_PERIOD':'time_period','OBS_VALUE':'obs_value_raw','SCALE':'scale','TRADE_FLOW':'trade_flow','VALUATION':'valuation','UNIT':'unit'}); df['raw_source_file']=str(p.relative_to(ROOT)); df['raw_source_sha256']=hashlib.sha256(p.read_bytes()).hexdigest(); frames.append(df); per.append({'country':p.stem.split('_')[2],'rows':int(len(df)),'counterparts':int(df.counterpart_country.nunique()),'years':sorted(pd.to_numeric(df.time_period,errors='coerce').dropna().astype(int).unique().tolist())})
all_df=pd.concat(frames,ignore_index=True); out=OUT/'IMF_IMTS_XG_OBSERVED_RECORDS_2000_2024.csv'; all_df.to_csv(out,index=False); profile={'source':'IMF.STA:IMTS','dataset_urn':'IMF.STA:IMTS(1.0.0)','input_acquisition_summary':'campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/IMF_IMTS_WDI_READY_XG_ACQUISITION_SUMMARY_V2.json','reporter_count':int(all_df.country.nunique()),'row_count':int(len(all_df)),'partner_count':int(all_df.counterpart_country.nunique()),'year_min':int(pd.to_numeric(all_df.time_period,errors='coerce').min()),'year_max':int(pd.to_numeric(all_df.time_period,errors='coerce').max()),'indicators':sorted(all_df.indicator.dropna().unique().tolist()),'frequencies':sorted(all_df.frequency.dropna().unique().tolist()),'units':sorted(all_df.unit.dropna().unique().tolist()),'trade_flows':sorted(all_df.trade_flow.dropna().unique().tolist()),'valuations':sorted(all_df.valuation.dropna().unique().tolist()),'output_path':str(out.relative_to(ROOT)),'output_sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'per_reporter':per,'raw_total_bytes':int(sum(x.get('bytes',0) for x in ACQ['responses'])),'raw_files':len(files)}; (OUT/'IMF_IMTS_XG_OBSERVATIONS_PROFILE_V2.json').write_text(json.dumps(profile,ensure_ascii=False,indent=2)+'\n'); print(json.dumps({'reporter_count':profile['reporter_count'],'row_count':profile['row_count'],'partner_count':profile['partner_count'],'years':[profile['year_min'],profile['year_max']],'output_bytes':out.stat().st_size,'profile_sha256':profile['output_sha256']},ensure_ascii=False,indent=2))
